import { Injectable, inject } from '@angular/core';
import { PropuestasService } from '../../controllers/propuestas.service';
import { PropuestasAvancesService } from '../../controllers/propuestas-avances.service';
import { PropuestasModel } from '../../models/propuestas.model';
import {PropuestasAvancesModel} from "../../models/propuestas-avances.model";

export interface ReportePorFolio {
  folio: string;
  nombre: string;
  totalAcciones: number;
  accionesCompletadas: number;
  porcentajeCompletado: number;
  unidadAdministrativa: string;
  direccionSei: string;
  finalizado: boolean;
  fechaFinalizado?: Date;
  usuarioFinalizo?: string;
}

export interface ReportePorEstatus {
  estatus: string;
  total: number;
  porcentaje: number;
  color: string;
}

export interface AvanceGeneral {
  totalPropuestas: number;
  porcentajeAvance: number;
  propuestasATiempo: number;
  propuestasRetrasadas: number;
}

export interface FiltrosReporte {
  fechaInicio?: Date;
  fechaFin?: Date;
  unidadId?: number;
  direccionId?: string;
  estatusIds?: number[];
}


export interface ReportePorDireccion {
  direccion: string;
  totalPropuestas: number;
  totalAcciones: number;
  accionesCompletadas: number;
  porcentajeCompletado: number;
}

@Injectable({
  providedIn: 'root'
})
export class ReportesUtilsService {

  private propuestasService = inject(PropuestasService);
  private propuestasAvancesService = inject(PropuestasAvancesService);

  /**
   * Obtiene reportes agrupados por folio de propuesta
   */
  async getReportesPorFolio(filtros?: FiltrosReporte): Promise<ReportePorFolio[]> {
    try {
      // Obtener todas las propuestas con sus relaciones
      const response = await this.propuestasService.get({
        include: ['user', 'tiempo_actual_unidad', 'tiempo_esperado_unidad']
      });

      if (!response.status || !response.data) {
        return [];
      }

      let propuestas = response.data;

      // Aplicar filtros si existen
      if (filtros) {
        propuestas = this.aplicarFiltros(propuestas, filtros);
      }

      // Para cada propuesta, obtener sus avances
      const reportes: ReportePorFolio[] = [];

      // Obtener todos los IDs de propuestas para buscar sus últimos avances
      const propuestaIds = propuestas.map(p => p.id);
      const ultimosAvances = await this.getUltimosAvancesPorPropuestas(propuestaIds);

      for (const propuesta of propuestas) {
        // Obtener el último avance de esta propuesta
        const ultimoAvance = ultimosAvances.get(propuesta.id);

        // Calcular progreso usando lógica híbrida
        const porcentajeCompletado = this.calcularProgreso(propuesta, ultimoAvance);

        // Calcular requisitos completados basado en el porcentaje
        const requisitosCompletados = Math.round((propuesta.cantidad_esperada * porcentajeCompletado) / 100);

        // Determinar unidad administrativa y dirección SEI según tipo de usuario
        let unidadAdministrativa = 'N/A';
        let direccionSei = 'N/A';

        if (propuesta.user) {
          if (propuesta.user.user_type === 'EXTERNO' && propuesta.user.datos_iniciales) {
            // Usuarios externos tienen datos_iniciales con unidad_admin y oficina_titular
            unidadAdministrativa = propuesta.user.datos_iniciales.unidad_administrativa?.nombre ||
                                 propuesta.user.datos_iniciales.unidad_admin || 'N/A';
            direccionSei = propuesta.user.datos_iniciales.oficina_titular || 'N/A';
          } else if (propuesta.user.user_type === 'INTERNO') {
            // Usuarios internos - usar datos directamente del usuario si están disponibles
            // (aquí podríamos agregar campos específicos para usuarios internos si existen)
            unidadAdministrativa = 'Usuario Interno';
            direccionSei = 'Por asignar';
          }
        }

        reportes.push({
          folio: `PROP-${String(propuesta.id).padStart(5, '0')}`,
          nombre: propuesta.nombre,
          totalAcciones: propuesta.cantidad_esperada,
          accionesCompletadas: requisitosCompletados,
          porcentajeCompletado: Math.round(porcentajeCompletado * 100) / 100, // Redondear a 2 decimales
          unidadAdministrativa,
          direccionSei,
          finalizado: !!propuesta.finalizado, // Convertir a boolean
          fechaFinalizado: propuesta.fecha_finalizado,
          usuarioFinalizo: propuesta.usuario_finalizo
        });
      }

      return reportes;
    } catch (error) {
      console.error('Error en getReportesPorFolio:', error);
      return [];
    }
  }

  /**
   * Obtiene reportes agrupados por estatus de acción de mejora
   */
  async getReportesPorEstatus(filtros?: FiltrosReporte): Promise<ReportePorEstatus[]> {
    try {
      const response = await this.propuestasAvancesService.get({
        include: ['tipo_avance', 'propuesta.user']
      });

      if (!response.status || !response.data) {
        return [];
      }

      let avances = response.data;

      // Aplicar filtros si existen
      if (filtros) {
        const propuestasFiltradas = await this.propuestasService.get({
          include: ['user']
        });

        if (propuestasFiltradas.status && propuestasFiltradas.data) {
          const propuestasIds = this.aplicarFiltros(propuestasFiltradas.data, filtros)
            .map(p => p.id);
          avances = avances.filter(a => propuestasIds.includes(a.propuesta_id));
        }
      }

      // Agrupar por estatus
      const agrupados = avances.reduce((acc, avance) => {
        const estatus = avance.tipo_avance?.nombre || 'Sin definir';
        acc[estatus] = (acc[estatus] || 0) + 1;
        return acc;
      }, {} as Record<string, number>);

      const total = Object.values(agrupados).reduce((sum, count) => sum + count, 0);

      const colores: Record<string, string> = {
        'Iniciada': '#28a745',
        'En proceso': '#ffc107',
        'Terminada': '#007bff',
        'Cancelada': '#dc3545',
        'Sin definir': '#6c757d'
      };

      return Object.entries(agrupados).map(([estatus, count]) => ({
        estatus,
        total: count,
        porcentaje: total > 0 ? (count / total) * 100 : 0,
        color: colores[estatus] || colores['Sin definir']
      }));
    } catch (error) {
      console.error('Error en getReportesPorEstatus:', error);
      return [];
    }
  }

  /**
   * Obtiene el avance general del Programa de Mejora Regulatoria
   */
  async getAvanceGeneral(filtros?: FiltrosReporte): Promise<AvanceGeneral> {
    try {
      const propuestasResponse = await this.propuestasService.get({ include: ['user'] });

      if (!propuestasResponse.status) {
        return {
          totalPropuestas: 0,
          porcentajeAvance: 0,
          propuestasATiempo: 0,
          propuestasRetrasadas: 0
        };
      }

      let propuestas = propuestasResponse.data!;

      // Aplicar filtros si existen
      if (filtros) {
        propuestas = this.aplicarFiltros(propuestas, filtros);
      }

      const totalPropuestas = propuestas.length;

      // Obtener los últimos avances de todas las propuestas
      const propuestaIds = propuestas.map(p => p.id);
      const ultimosAvances = await this.getUltimosAvancesPorPropuestas(propuestaIds);

      // Calcular porcentaje de avance general como promedio de los últimos avances
      let sumaPorcentajes = 0;
      let propuestasConAvance = 0;

      for (const propuesta of propuestas) {
        const ultimoAvance = ultimosAvances.get(propuesta.id);
        const progreso = this.calcularProgreso(propuesta, ultimoAvance);

        sumaPorcentajes += progreso;
        propuestasConAvance++;
      }

      // Calcular promedio de progreso
      const porcentajeAvance = propuestasConAvance > 0
        ? sumaPorcentajes / propuestasConAvance
        : 0;

      // Mantener cálculos de tiempo existentes
      const hoy = new Date();
      const propuestasATiempo = propuestas.filter(p =>
        new Date(p.fecha_cumplimiento) >= hoy
      ).length;

      const propuestasRetrasadas = totalPropuestas - propuestasATiempo;

      return {
        totalPropuestas,
        porcentajeAvance: Math.round(porcentajeAvance * 100) / 100, // Redondear a 2 decimales
        propuestasATiempo,
        propuestasRetrasadas
      };
    } catch (error) {
      console.error('Error en getAvanceGeneral:', error);
      return {
        totalPropuestas: 0,
        porcentajeAvance: 0,
        propuestasATiempo: 0,
        propuestasRetrasadas: 0
      };
    }
  }

  
  /**
   * Obtiene reportes agrupados por dirección SEI
   */
  async getReportesPorDireccion(filtros?: FiltrosReporte): Promise<ReportePorDireccion[]> {
    try {
      const reportesPorFolio = await this.getReportesPorFolio(filtros);

      const agrupados = reportesPorFolio.reduce((acc, reporte) => {
        const direccion = reporte.direccionSei;
        if (!acc[direccion]) {
          acc[direccion] = {
            direccion,
            totalPropuestas: 0,
            totalAcciones: 0,
            accionesCompletadas: 0,
            porcentajeCompletado: 0
          };
        }
        acc[direccion].totalPropuestas++;
        acc[direccion].totalAcciones += reporte.totalAcciones;
        acc[direccion].accionesCompletadas += reporte.accionesCompletadas;
        return acc;
      }, {} as Record<string, ReportePorDireccion>);

      // Calcular porcentajes
      return Object.values(agrupados).map((grupo) => ({
        ...grupo,
        porcentajeCompletado: grupo.totalAcciones > 0
          ? (grupo.accionesCompletadas / grupo.totalAcciones) * 100
          : 0
      }));
    } catch (error) {
      console.error('Error en getReportesPorDireccion:', error);
      return [];
    }
  }

  /**
   * Aplica filtros a las propuestas
   */
  private aplicarFiltros(propuestas: PropuestasModel[], filtros: FiltrosReporte): PropuestasModel[] {
    return propuestas.filter(propuesta => {
      if (filtros.fechaInicio && new Date(propuesta.fecha_cumplimiento) < filtros.fechaInicio) {
        return false;
      }
      if (filtros.fechaFin && new Date(propuesta.fecha_cumplimiento) > filtros.fechaFin) {
        return false;
      }
      if (filtros.unidadId && propuesta.user?.datos_iniciales?.unidad_administrativa?.id !== filtros.unidadId) {
        return false;
      }
      if (filtros.direccionId && propuesta.user?.datos_iniciales?.oficina_titular !== filtros.direccionId) {
        return false;
      }
      return true;
    });
  }

  /**
   * Obtiene el último avance de una propuesta por fecha
   * @param avances Lista de avances de la propuesta
   * @returns Avance más reciente o undefined si no hay avances
   */
  private getUltimoAvance(avances: PropuestasAvancesModel[]): PropuestasAvancesModel | undefined {
    if (!avances || avances.length === 0) return undefined;

    return avances.reduce((ultimo, actual) => {
      const fechaUltimo = new Date(ultimo.fecha_avance);
      const fechaActual = new Date(actual.fecha_avance);
      return fechaActual > fechaUltimo ? actual : ultimo;
    });
  }

  /**
   * Obtiene los últimos avances para múltiples propuestas
   * @param propuestaIds Lista de IDs de propuestas
   * @returns Map con propuesta_id como clave y último avance como valor
   */
  private async getUltimosAvancesPorPropuestas(propuestaIds: number[]): Promise<Map<number, PropuestasAvancesModel>> {
    const ultimosAvances = new Map<number, PropuestasAvancesModel>();

    if (!propuestaIds || propuestaIds.length === 0) {
      return ultimosAvances;
    }

    try {
      // Obtener avances para cada propuesta individualmente
      const promises = propuestaIds.map(async (propuestaId) => {
        try {
          const response = await this.propuestasAvancesService.get({
            conditionals: [
              { key: 'propuesta_id', operator: '=', value: propuestaId },
              { key: 'deleted_at', operator: 'IS NULL', value: null }
            ],
            relations: ['tipo_avance'],
            loader: false
          });

          if (response.status && response.data && response.data.length > 0) {
            const ultimoAvance = this.getUltimoAvance(response.data);
            if (ultimoAvance) {
              ultimosAvances.set(propuestaId, ultimoAvance);
            }
          }
        } catch (error) {
          console.warn(`Error obteniendo avances para propuesta ${propuestaId}:`, error);
        }
      });

      // Esperar a que todas las promesas se resuelvan
      await Promise.all(promises);

      return ultimosAvances;
    } catch (error) {
      console.error('Error en getUltimosAvancesPorPropuestas:', error);
      return ultimosAvances;
    }
  }

  /**
   * Calcula el progreso usando lógica híbrida: finalizado prioritario sobre avances y cantidades
   * @param propuesta Datos de la propuesta
   * @param ultimoAvance Último avance registrado (opcional)
   * @returns Porcentaje de progreso (0-100)
   */
  private calcularProgreso(propuesta: PropuestasModel, ultimoAvance?: PropuestasAvancesModel): number {
    // Nueva Prioridad 1: Usar campo finalizado del modelo (máxima prioridad)
    if (propuesta.finalizado) {
      return 100;
    }

    // Prioridad 2: Usar avance más reciente si existe
    if (ultimoAvance) {
      // Lógica híbrida: si el tipo de avance es "Terminada", asegurar 100%
      if (ultimoAvance.tipo_avance?.nombre?.toLowerCase() === 'terminada') {
        return 100;
      }
      return ultimoAvance.porcentaje || 0;
    }

    // Prioridad 3: Usar campos de cantidad del modelo
    if (propuesta.cantidad_esperada > 0) {
      return (propuesta.cantidad_actual / propuesta.cantidad_esperada) * 100;
    }

    // Prioridad 4: Sin datos, retornar 0
    return 0;
  }

  /**
   * Calcula el porcentaje de cumplimiento de una propuesta basándose en sus avances
   * @param avances Lista de avances de la propuesta
   * @returns Porcentaje de cumplimiento (0-100)
   */
  getPorcentajeCumplimiento(avances: PropuestasAvancesModel[]): number {
    const ultimoAvance = this.getUltimoAvance(avances);
    return ultimoAvance ? ultimoAvance.porcentaje || 0 : 0;
  }
}