import { Component, OnInit, inject } from '@angular/core';
import { ActivatedRoute, Router, RouterModule } from '@angular/router';
import { CommonModule, DatePipe } from '@angular/common';
import { PropuestasService } from '../../../controllers/propuestas.service';
import { PropuestaEvidenciaService } from '../../../controllers/propuesta-evidencia.service';
import { PropuestasAvancesService } from '../../../controllers/propuestas-avances.service';
import { PropuestasDocumentosService } from '../../../controllers/propuestas-documentos.service';
import { PropuestasModel } from '../../../models/propuestas.model';
import { PropuestaEvidenciaModel } from '../../../models/propuesta-evidencia.model';
import { PropuestasAvancesModel } from '../../../models/propuestas-avances.model';
import { FeedbackInterno } from './feedback-interno/feedback-interno';
import { EvidenciasComponent } from './evidencias-component/evidencias-component';
import {Pdf} from "../../services/pdf";

@Component({
  selector: 'app-detalle-propuesta',
  imports: [
    CommonModule,
    RouterModule,
    FeedbackInterno,
    EvidenciasComponent
  ],
  providers: [
    DatePipe
  ],
  templateUrl: './detalle-propuesta.html',
  styleUrl: './detalle-propuesta.css'
})
export class DetallePropuesta implements OnInit {
  private route = inject(ActivatedRoute);
  private router = inject(Router);
  private propuestasService = inject(PropuestasService);
  private evidenciaService = inject(PropuestaEvidenciaService);
  private avancesService = inject(PropuestasAvancesService);
  private propuestasDocumentosService = inject(PropuestasDocumentosService);
  private datePipe = inject(DatePipe);
  private pdfService = inject(Pdf);

  propuestaId: number | null = null;
  propuesta: PropuestasModel | null = null;
  evidencias: PropuestaEvidenciaModel[] = [];
  avances: PropuestasAvancesModel[] = [];
  isLoading = true;
  isLoadingEvidencias = false;
  isFinalizando = false;
  successMessage: string | null = null;
  error: string | null = null;

  ngOnInit(): void {
    this.route.paramMap.subscribe((params) => {
      const idParam = params.get('id');
      if (idParam) {
        const id = parseInt(idParam, 10);
        if (!isNaN(id)) {
          this.propuestaId = id;
          void this.cargarDatosPropuesta();
        } else {
          this.error = 'ID de propuesta inválido';
          this.isLoading = false;
        }
      } else {
        this.error = 'No se proporcionó ID de propuesta';
        this.isLoading = false;
      }
    });
  }

  async cargarDatosPropuesta(): Promise<void> {
    if (!this.propuestaId) return;

    try {
      this.isLoading = true;
      this.error = null;

      // Cargar datos principales de la propuesta con relaciones
      const propuestaResponse = await this.propuestasService.get({
        relations: ['user', 'tiempoActualUnidad', 'tiempoEsperadoUnidad', 'documentos'],
        conditionals: [
          { key: 'id', operator: '=', value: this.propuestaId }
        ]
      });

      if (propuestaResponse.status && propuestaResponse.data && propuestaResponse.data.length > 0) {
        this.propuesta = propuestaResponse.data[0];
      } else {
        this.error = 'No se encontró la propuesta solicitada';
        this.isLoading = false;
        return;
      }

      // Cargar datos relacionados en paralelo
      await Promise.all([
        this.cargarEvidencias(),
        this.cargarAvances()
      ]);

    } catch (error) {
      console.error('Error al cargar datos de la propuesta:', error);
      this.error = 'Error al cargar los datos de la propuesta';
    } finally {
      this.isLoading = false;
    }
  }

  async cargarEvidencias(): Promise<void> {
    if (!this.propuestaId) return;

    try {
      const evidenciasResponse = await this.evidenciaService.get({
        conditionals: [
          { key: 'propuesta_id', operator: '=', value: this.propuestaId }
        ],
        orderBy: { column: 'createdAt', direction: 'desc' }
      });

      if (evidenciasResponse.status && evidenciasResponse.data) {
        this.evidencias = evidenciasResponse.data;
      }
    } catch (error) {
      console.error('Error al cargar evidencias:', error);
    }
  }

  async cargarAvances(): Promise<void> {
    if (!this.propuestaId) return;

    try {
      const avancesResponse = await this.avancesService.get({
        conditionals: [
          { key: 'propuesta_id', operator: '=', value: this.propuestaId }
        ],
        orderBy: { column: 'fecha_avance', direction: 'desc' }
      });

      if (avancesResponse.status && avancesResponse.data) {
        this.avances = avancesResponse.data;
      }
    } catch (error) {
      console.error('Error al cargar avances:', error);
    }
  }

  async regresar(): Promise<void> {
    await this.router.navigate(['/main/internos/propuestas-registradas']);
  }

  /**
   * Genera y descarga el PDF del reporte de la propuesta
   */
  async generarPdf(): Promise<void> {
    // Validar que los datos necesarios estén disponibles
    if (!this.propuesta) {
      console.error('No hay datos de la propuesta para generar el PDF');
      return;
    }

    try {
      // Generar PDF con los datos actuales de la propuesta, evidencias y avances
      await this.pdfService.reportePropuesta(this.propuesta, this.evidencias, this.avances, {
        includeTimestamp: false,
        includePageNumbers: false,
        title: 'Reporte de Propuesta'
      });

      console.log('PDF generado exitosamente');
    } catch (error) {
      console.error('Error al generar el PDF:', error);
      // Aquí podrías mostrar un mensaje de error al usuario si lo deseas
    }
  }

  // Utilidades de formato
  formatearFecha(fecha: string | Date | null | undefined): string {
    if (!fecha) return 'N/A';
    return this.datePipe.transform(fecha, 'dd/MM/yyyy') || 'N/A';
  }

  getDiasRestantes(fecha: string | Date | null | undefined): string {
    if (!fecha) return 'N/A';

    const fechaLimite = new Date(fecha);
    const hoy = new Date();
    const diferencia = fechaLimite.getTime() - hoy.getTime();
    const dias = Math.ceil(diferencia / (1000 * 60 * 60 * 24));

    if (dias < 0) {
      return `Vencida hace ${Math.abs(dias)} días`;
    } else if (dias === 0) {
      return 'Vence hoy';
    } else if (dias === 1) {
      return 'Vence mañana';
    } else {
      return `Faltan ${dias} días`;
    }
  }

  getEstadoClase(fecha: string | Date | null | undefined): string {
    if (!fecha) return '';

    const fechaLimite = new Date(fecha);
    const hoy = new Date();
    const dias = Math.ceil((fechaLimite.getTime() - hoy.getTime()) / (1000 * 60 * 60 * 24));

    if (dias < 0) {
      return 'text-danger';
    } else if (dias <= 7) {
      return 'text-warning';
    } else {
      return 'text-success';
    }
  }

  getTipoPropuestaClase(tipo: string): string {
    return tipo === 'Tramite'
      ? 'bg-info-subtle text-info-emphasis'
      : 'bg-success-subtle text-success-emphasis';
  }

  getTipoPropuestaIcono(tipo: string): string {
    return tipo === 'Tramite'
      ? 'bi bi-file-text'
      : 'bi bi-gear';
  }

  /**
   * Manejar descarga de evidencia
   */
  async descargarEvidencia(evidenciaId: number): Promise<void> {
    if (!this.propuestaId) return;

    try {
      this.isLoadingEvidencias = true;

      // Obtener la URL de descarga usando el servicio
      const downloadUrl = this.evidenciaService.getUrlDocsPropuestas(evidenciaId);

      // Crear un elemento link temporal para la descarga
      const link = document.createElement('a');
      link.href = downloadUrl;
      link.download = ''; // Deja que el navegador determine el nombre del archivo
      link.style.display = 'none';

      // Agregar al DOM, hacer clic y remover
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

    } catch (error) {
      console.error('Error al descargar evidencia:', error);
      // TODO: Mostrar mensaje de error al usuario - podrías usar un toast o alerta
      alert('Error al descargar el archivo. Por favor, intente nuevamente.');
    } finally {
      this.isLoadingEvidencias = false;
    }
  }

  /**
   * Manejar descarga de documento del plan de trabajo
   */
  async descargarDocumento(documentoId: number): Promise<void> {
    if (!this.propuestaId) return;

    try {
      // Obtener la URL de descarga usando el servicio
      const downloadUrl = this.propuestasDocumentosService.getUrlDocsPropuestas(documentoId);

      // Crear un elemento link temporal para la descarga
      const link = document.createElement('a');
      link.href = downloadUrl;
      link.download = ''; // Deja que el navegador determine el nombre del archivo
      link.style.display = 'none';

      // Agregar al DOM, hacer clic y remover
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);

    } catch (error) {
      console.error('Error al descargar documento:', error);
      alert('Error al descargar el archivo. Por favor, intente nuevamente.');
    }
  }

  /**
   * Finaliza la propuesta actual
   */
  async finalizarPropuesta(): Promise<void> {
    if (!this.propuestaId || !this.propuesta || this.propuesta.finalizado || this.isFinalizando) {
      return;
    }

    // Confirmación antes de finalizar
    const confirmado = confirm(
      `¿Está seguro que desea finalizar la propuesta "${this.propuesta.nombre}"?\n\n` +
      'Esta acción marcará la propuesta como completada y no podrá ser modificada.'
    );

    if (!confirmado) {
      return;
    }

    try {
      this.isFinalizando = true;
      this.error = null;
      this.successMessage = null;

      // Llamar al servicio con loader=true para mostrar indicador global
      const response = await this.propuestasService.finalizarPropuesta(this.propuestaId, true);

      if (response.status && response.data) {
        // Actualizar los datos de la propuesta con la respuesta
        this.propuesta = response.data;
        this.successMessage = 'Propuesta finalizada exitosamente';

        // Mostrar mensaje de éxito
        alert('Propuesta finalizada exitosamente');
      } else {
        throw new Error(response.message || 'Error al finalizar la propuesta');
      }

    } catch (error) {
      console.error('Error al finalizar propuesta:', error);
      this.error = 'No se pudo finalizar la propuesta. Por favor, intente nuevamente.';

      // Mostrar mensaje de error al usuario
      alert('Error al finalizar la propuesta: ' + (error instanceof Error ? error.message : 'Error desconocido'));
    } finally {
      this.isFinalizando = false;
    }
  }

  /**
   * Verifica si la propuesta puede ser finalizada
   */
  get puedeFinalizar(): boolean {
    return !!(this.propuesta &&
             !this.propuesta.finalizado &&
             this.propuestaId &&
             !this.isFinalizando);
  }
}
