/* eslint-disable @typescript-eslint/no-explicit-any */
import { Injectable, inject } from '@angular/core';
import { HttpClient } from '@angular/common/http';
import { PropuestasModel } from '../../models/propuestas.model';
import { PropuestaEvidenciaModel } from '../../models/propuesta-evidencia.model';
import { PropuestasAvancesModel } from '../../models/propuestas-avances.model';
import { ReportePorFolio, ReportePorEstatus, AvanceGeneral } from './reportes-utils.service';

// Importar pdfmake de forma estándar para Angular
import * as pdfMake from 'pdfmake/build/pdfmake';
import 'pdfmake/build/vfs_fonts';

// Verificar si pdfMake está disponible
let pdfMakeInstance: any = null;

// Inicializar pdfMake solo en el navegador
if (typeof window !== 'undefined') {
  pdfMakeInstance = pdfMake;
}

// Cache para el logo base64
let logoCache: string | null = null;

export interface PdfReportePropuestaOptions {
  includeTimestamp?: boolean;
  includePageNumbers?: boolean;
  title?: string;
}

@Injectable({
  providedIn: 'root'
})
export class Pdf {
  private http = inject(HttpClient);

  /**
   * Genera un PDF con el reporte general del PMR
   * @param avanceGeneral Datos del avance general
   * @param reportesPorFolio Reportes agrupados por folio
   * @param reportesPorEstatus Reportes agrupados por estatus
   * @param options Opciones adicionales para el reporte
   * @returns Promise<void> - Inicia la descarga del PDF
   */
  async reporteGeneralPMR(
    avanceGeneral: AvanceGeneral,
    reportesPorFolio: ReportePorFolio[],
    reportesPorEstatus: ReportePorEstatus[],
    options: PdfReportePropuestaOptions = {}
  ): Promise<void> {
    if (!pdfMakeInstance) {
      console.error('pdfMake no está disponible en el navegador');
      return;
    }

    const {
      includeTimestamp = true,
      includePageNumbers = true,
      title = 'Reporte General del Programa de Mejora Regulatoria'
    } = options;

    // Construir el header de forma asíncrona
    const header = await this.buildHeader(title, includeTimestamp);

    const content: any[] = [
      // Header
      ...header,

      // Resumen General
      ...this.buildResumenGeneral(avanceGeneral),

      // Tabla de Reportes por Folio
      ...this.buildReportesPorFolioTable(reportesPorFolio),

      // Distribución por Estatus
      ...this.buildDistribucionEstatus(reportesPorEstatus)
    ];

    const documentDefinition = {
      content,
      footer: includePageNumbers ? this.buildFooter() : undefined,
      styles: this.getStyles(),
      defaultStyle: {
        font: 'Roboto',
        fontSize: 10
      }
    };

    const pdfDoc = pdfMakeInstance.createPdf(documentDefinition);
    // Abrir PDF en una nueva ventana en lugar de descargar
    pdfDoc.open({}, window.open('', '_blank') || undefined);
  }

  /**
   * Genera un PDF con el reporte de una propuesta y sus evidencias
   * @param propuesta Datos de la propuesta
   * @param evidencias Lista de evidencias asociadas
   * @param avances Lista de avances asociados
   * @param options Opciones adicionales para el reporte
   * @returns Promise<void> - Inicia la descarga del PDF
   */
  async reportePropuesta(
    propuesta: PropuestasModel,
    evidencias: PropuestaEvidenciaModel[],
    avances: PropuestasAvancesModel[],
    options: PdfReportePropuestaOptions = {}
  ): Promise<void> {
    if (!pdfMakeInstance) {
      console.error('pdfMake no está disponible en el navegador');
      return;
    }

    const {
      includeTimestamp = true,
      includePageNumbers = true,
      title = 'Reporte de Propuesta'
    } = options;

    // Construir el header de forma asíncrona
    const header = await this.buildHeader(title, includeTimestamp);

    const documentDefinition = {
      content: [
        // Header
        ...header,

        // Información General de la Propuesta
        ...this.buildInformacionGeneral(propuesta),

        // Métricas Comparativas
        ...this.buildMetricasComparativas(propuesta),

        // Información del Creador
        ...this.buildInformacionCreador(propuesta),

        // Listado de Avances
        ...this.buildAvancesTable(avances)
      ],

      footer: includePageNumbers ? this.buildFooter() : undefined,

      styles: this.getStyles(),

      defaultStyle: {
        font: 'Roboto',
        fontSize: 10
      }
    };

    const pdfDoc = pdfMakeInstance.createPdf(documentDefinition);
    // Abrir PDF en una nueva ventana en lugar de descargar
    pdfDoc.open({}, window.open('', '_blank') || undefined);
  }

  /**
   * Construye el header del PDF con título y logo
   */
  private async buildHeader(title: string, includeTimestamp: boolean): Promise<any[]> {
    const logoBase64 = await this.getLogoBase64();

    return [
      {
        // Header con logo y título a la izquierda
        columns: [
          {
            width: '20%',
            image: logoBase64 ? `data:image/png;base64,${logoBase64}` : '',
            fit: [80, 80], // Tamaño reducido del logo
            margin: [10, 5, 0, 5]
          },
          {
            width: '65%',
            stack: [
              {
                text: title,
                style: 'headerTitle',
                alignment: 'left',
                margin: [0, 10, 0, 2]
              },
              {
                text: 'Secretaría de Economía e Innovación',
                style: 'headerSubtitle',
                alignment: 'left',
                margin: [0, 0, 0, 5]
              }
            ]
          },
          {
            width: '15%',
            text: includeTimestamp ? this.formatFecha(new Date()) : '',
            style: 'headerDate',
            alignment: 'right',
            margin: [0, 15, 10, 5]
          }
        ],
        margin: [0, 0, 0, 5] // Reducido de 15 a 5 para compactar
      }
    ];
  }

  /**
   * Construye la sección de resumen general
   */
  private buildResumenGeneral(avanceGeneral: AvanceGeneral): any[] {
    return [
      {
        text: 'Resumen General del Programa',
        style: 'sectionTitle',
        margin: [0, 10, 0, 5]
      },
      {
        table: {
          widths: ['50%', '50%'],
          body: [
            [{ text: 'Métrica', style: 'tableHeader' }, { text: 'Valor', style: 'tableHeader' }],
            [{ text: 'Total de Propuestas', style: 'tableCell' }, { text: avanceGeneral.totalPropuestas.toString(), style: 'tableCell' }],
            [{ text: 'Porcentaje de Avance General', style: 'tableCell' }, { text: `${avanceGeneral.porcentajeAvance.toFixed(1)}%`, style: 'tableCell' }],
            [{ text: 'Propuestas a Tiempo', style: 'tableCell' }, { text: avanceGeneral.propuestasATiempo.toString(), style: 'tableCell' }],
            [{ text: 'Propuestas con Retraso', style: 'tableCell' }, { text: avanceGeneral.propuestasRetrasadas.toString(), style: 'tableCell' }]
          ]
        },
        layout: 'noBorders',
        margin: [0, 0, 0, 10]
      },
      this.getSeparator()
    ];
  }

  /**
   * Construye la tabla de reportes por folio
   */
  private buildReportesPorFolioTable(reportesPorFolio: ReportePorFolio[]): any[] {
    if (!reportesPorFolio || reportesPorFolio.length === 0) {
      return [
        {
          text: 'Reportes por Folio',
          style: 'sectionTitle',
          margin: [0, 10, 0, 5]
        },
        {
          text: 'No hay datos disponibles para mostrar.',
          style: 'noData',
          margin: [0, 0, 0, 10]
        }
      ];
    }

    const tableBody: any[][] = [
      [
        { text: 'Folio', style: 'tableHeader' },
        { text: 'Nombre de Propuesta', style: 'tableHeader' },
        { text: 'Unidad Administrativa', style: 'tableHeader' },
        { text: 'Total Acciones', style: 'tableHeader' },
        { text: 'Acciones Completadas', style: 'tableHeader' },
        { text: '% Completado', style: 'tableHeader' }
      ]
    ];

    reportesPorFolio.forEach(reporte => {
      tableBody.push([
        { text: reporte.folio, style: 'tableCell' },
        { text: reporte.nombre, style: 'tableCell' },
        { text: reporte.unidadAdministrativa, style: 'tableCell' },
        { text: reporte.totalAcciones.toString(), style: 'tableCell' },
        { text: reporte.accionesCompletadas.toString(), style: 'tableCell' },
        { text: `${reporte.porcentajeCompletado.toFixed(1)}%`, style: 'tableCell' }
      ]);
    });

    return [
      {
        text: 'Reportes por Folio',
        style: 'sectionTitle',
        margin: [0, 10, 0, 5]
      },
      {
        table: {
          widths: ['15%', '35%', '20%', '10%', '10%', '10%'],
          body: tableBody
        },
        layout: 'noBorders',
        margin: [0, 0, 0, 10]
      },
      this.getSeparator()
    ];
  }

  /**
   * Construye la sección de distribución por estatus
   */
  private buildDistribucionEstatus(reportesPorEstatus: ReportePorEstatus[]): any[] {
    if (!reportesPorEstatus || reportesPorEstatus.length === 0) {
      return [
        {
          text: 'Distribución por Estatus',
          style: 'sectionTitle',
          margin: [0, 10, 0, 5]
        },
        {
          text: 'No hay datos disponibles para mostrar.',
          style: 'noData',
          margin: [0, 0, 0, 10]
        }
      ];
    }

    const tableBody: any[][] = [
      [
        { text: 'Estatus', style: 'tableHeader' },
        { text: 'Total', style: 'tableHeader' },
        { text: 'Porcentaje', style: 'tableHeader' }
      ]
    ];

    reportesPorEstatus.forEach(estatus => {
      tableBody.push([
        { text: estatus.estatus, style: 'tableCell' },
        { text: estatus.total.toString(), style: 'tableCell' },
        { text: `${estatus.porcentaje.toFixed(1)}%`, style: 'tableCell' }
      ]);
    });

    return [
      {
        text: 'Distribución por Estatus',
        style: 'sectionTitle',
        margin: [0, 10, 0, 5]
      },
      {
        table: {
          widths: ['50%', '25%', '25%'],
          body: tableBody
        },
        layout: 'noBorders',
        margin: [0, 0, 0, 10]
      }
    ];
  }

  /**
   * Construye la sección de información general
   */
  private buildInformacionGeneral(propuesta: PropuestasModel): any[] {
    return [
      {
        text: 'Información General',
        style: 'sectionTitle',
        margin: [0, 10, 0, 5] // Reducido para compactar
      },
      {
        table: {
          widths: ['30%', '70%'],
          body: [
            [{ text: 'Nombre de la Propuesta:', style: 'tableHeader' }, { text: propuesta.nombre, style: 'tableCell' }],
            [{ text: 'Tipo:', style: 'tableHeader' }, { text: this.getTipoBadge(propuesta.tipo), style: 'tableCell' }],
            [{ text: 'Descripción:', style: 'tableHeader' }, { text: propuesta.descripcion || 'N/A', style: 'tableCell' }],
            [{ text: 'Fecha Límite:', style: 'tableHeader' }, { text: this.formatFecha(propuesta.fecha_cumplimiento), style: 'tableCell' }],
            [{ text: 'Estado:', style: 'tableHeader' }, { text: this.getEstadoBadge(propuesta.fecha_cumplimiento), style: 'tableCell' }]
          ]
        },
        layout: 'noBorders',
        margin: [0, 0, 0, 8] // Reducido para compactar
      }
    ];
  }

  /**
   * Construye la sección de métricas comparativas
   */
  private buildMetricasComparativas(propuesta: PropuestasModel): any[] {
    return [
      {
        text: 'Métricas Comparativas',
        style: 'sectionTitle',
        margin: [0, 8, 0, 5] // Reducido para compactar
      },
      {
        table: {
          widths: ['30%', '35%', '35%'], // Ajustado para 3 columnas sin cumplimiento
          body: [
            [
              { text: 'Métrica', style: 'tableHeader' },
              { text: 'Valor Actual', style: 'tableHeader' },
              { text: 'Valor Esperado', style: 'tableHeader' }
            ],
            [
              { text: 'Tiempo Actual', style: 'tableCell' },
              { text: `${propuesta.tiempo_actual} ${propuesta.tiempo_actual_unidad?.nombre || 'unidades'}`, style: 'tableCell', alignment: 'right' },
              { text: `${propuesta.tiempo_esperado} ${propuesta.tiempo_esperado_unidad?.nombre || 'unidades'}`, style: 'tableCell', alignment: 'right' }
            ],
            [
              { text: 'Requisitos', style: 'tableCell' },
              { text: propuesta.cantidad_actual.toString(), style: 'tableCell', alignment: 'right' },
              { text: propuesta.cantidad_esperada.toString(), style: 'tableCell', alignment: 'right' }
            ]
          ]
        },
        layout: 'noBorders',
        margin: [0, 0, 0, 8] // Reducido para compactar
      }
    ];
  }

  /**
   * Construye la sección de información del creador
   */
  private buildInformacionCreador(propuesta: PropuestasModel): any[] {
    if (!propuesta.user) return [];

    return [
      {
        text: 'Información del Creador',
        style: 'sectionTitle',
        margin: [0, 8, 0, 5] // Reducido para compactar
      },
      {
        table: {
          widths: ['30%', '70%'],
          body: [
            [{ text: 'Nombre:', style: 'tableHeader' }, { text: propuesta.user.name, style: 'tableCell' }],
            [{ text: 'Email:', style: 'tableHeader' }, { text: propuesta.user.email, style: 'tableCell' }],
            [{ text: 'Tipo de Usuario:', style: 'tableHeader' }, { text: this.getTipoUsuarioBadge(propuesta.user.user_type), style: 'tableCell' }]
          ]
        },
        layout: 'noBorders',
        margin: [0, 0, 0, 8] // Reducido para compactar
      }
    ];
  }

  /**
   * Construye la tabla de avances
   */
  private buildAvancesTable(avances: PropuestasAvancesModel[]): any[] {
    if (!avances || avances.length === 0) {
      return [
        {
          text: 'Avances',
          style: 'sectionTitle',
          margin: [0, 8, 0, 5] // Reducido para compactar
        },
        {
          text: 'No hay avances registrados para esta propuesta.',
          style: 'noData',
          margin: [0, 0, 0, 8] // Reducido para compactar
        }
      ];
    }

    const tableBody: any[][] = [
      [
        { text: 'Tipo de Avance', style: 'tableHeader' },
        { text: 'Descripción', style: 'tableHeader' },
        { text: 'Fecha', style: 'tableHeader' },
        { text: 'Porcentaje', style: 'tableHeader' }
      ]
    ];

    // Ordenar avances por fecha descendente
    const avancesOrdenados = [...avances].sort((a, b) =>
      new Date(b.fecha_avance).getTime() - new Date(a.fecha_avance).getTime()
    );

    avancesOrdenados.forEach(avance => {
      tableBody.push([
        { text: avance.tipo_avance?.nombre || 'Avance', style: 'tableCell' },
        { text: avance.avance || 'Sin descripción', style: 'tableCell' },
        { text: this.formatFecha(avance.fecha_avance), style: 'tableCell' },
        { text: `${avance.porcentaje || 0}%`, style: 'tableCell' }
      ]);
    });

    return [
      {
        text: `Avances (${avances.length})`,
        style: 'sectionTitle',
        margin: [0, 8, 0, 5] // Reducido para compactar
      },
      {
        table: {
          widths: ['25%', '40%', '20%', '15%'],
          body: tableBody
        },
        layout: 'noBorders',
        margin: [0, 0, 0, 8] // Reducido para compactar
      }
    ];
  }

  /**
   * Construye la tabla de evidencias
   */
  private buildEvidenciasTable(evidencias: PropuestaEvidenciaModel[]): any[] {
    if (!evidencias || evidencias.length === 0) {
      return [
        {
          text: 'Evidencias',
          style: 'sectionTitle',
          margin: [0, 20, 0, 10]
        },
        {
          text: 'No hay evidencias asociadas a esta propuesta.',
          style: 'noData',
          margin: [0, 0, 0, 8] // Reducido para compactar
        }
      ];
    }

    const tableBody: any[][] = [
      [
        { text: 'Nombre del Archivo', style: 'tableHeader' },
        { text: 'Tamaño', style: 'tableHeader' },
        { text: 'Tipo', style: 'tableHeader' },
        { text: 'Fecha de Carga', style: 'tableHeader' }
      ]
    ];

    evidencias.forEach(evidencia => {
      tableBody.push([
        { text: evidencia.nombre, style: 'tableCell' },
        { text: this.formatFileSize(evidencia.tamano), style: 'tableCell' },
        { text: evidencia.tipo, style: 'tableCell' },
        { text: evidencia.created_at ? this.formatFecha(evidencia.created_at) : 'N/A', style: 'tableCell' }
      ]);
    });

    return [
      {
        text: `Evidencias (${evidencias.length})`,
        style: 'sectionTitle',
        margin: [0, 20, 0, 10]
      },
      {
        table: {
          widths: ['40%', '20%', '20%', '20%'],
          body: tableBody
        },
        layout: 'noBorders',
        margin: [0, 0, 0, 8] // Reducido para compactar
      }
    ];
  }

  /**
   * Construye el footer del PDF
   */
  private buildFooter(): any {
    return {
      columns: [
        { text: `Generado el ${this.formatFecha(new Date())}`, style: 'footer' },
        { text: 'Página ', style: 'footer' },
        { text: '{{pageNumber}}', style: 'footer' }
      ],
      margin: [40, 10, 40, 10]
    };
  }

  /**
   * Formatea una fecha para mostrar en el PDF
   */
  private formatFecha(fecha: Date | string): string {
    if (!fecha) return 'N/A';

    const date = typeof fecha === 'string' ? new Date(fecha) : fecha;
    return date.toLocaleDateString('es-MX', {
      day: '2-digit',
      month: '2-digit',
      year: 'numeric',
      hour: '2-digit',
      minute: '2-digit'
    });
  }

  /**
   * Formatea el tamaño de archivo
   */
  private formatFileSize(bytes: number): string {
    if (!bytes || bytes === 0) return 'N/A';

    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(1024));
    return Math.round(bytes / Math.pow(1024, i) * 100) / 100 + ' ' + sizes[i];
  }

  /**
   * Calcula el porcentaje de cumplimiento
   */
  private getPorcentajeCumplimiento(actual: number, esperado: number): string {
    if (!esperado || esperado === 0) return 'N/A';

    const porcentaje = Math.round((actual / esperado) * 100);
    return `${porcentaje}%`;
  }

  /**
   * Devuelve el badge para el tipo de propuesta
   */
  private getTipoBadge(tipo: string): string {
    return tipo === 'Tramite' ? 'TRÁMITE' : 'SERVICIO';
  }

  /**
   * Devuelve el badge para el estado según fecha límite
   */
  private getEstadoBadge(fechaLimite: Date): string {
    const hoy = new Date();
    const limite = new Date(fechaLimite);

    if (limite < hoy) {
      return 'VENCIDO';
    } else if (limite.getTime() - hoy.getTime() <= 7 * 24 * 60 * 60 * 1000) {
      return 'POR VENCER';
    } else {
      return 'EN TIEMPO';
    }
  }

  /**
   * Devuelve el badge para el tipo de usuario
   */
  private getTipoUsuarioBadge(tipo: string): string {
    return tipo === 'INTERNO' ? 'INTERNO' : 'EXTERNO';
  }

  /**
   * Devuelve un separador visual con color del gobierno
   */
  private getSeparator(): any {
    return {
      canvas: [
        { type: 'line', x1: 40, y1: 0, x2: 555, y2: 0, lineWidth: 2, lineColor: '#6a1c32' }
      ],
      margin: [0, 0, 0, 10]
    };
  }

  /**
   * Define los estilos del documento
   */
  private getStyles(): Record<string, any> {
    return {
      headerTitle: {
        fontSize: 18,
        bold: true,
        color: '#6a1c32', // Color primario gobierno
        margin: [0, 0, 0, 0]
      },
      headerSubtitle: {
        fontSize: 12,
        color: '#6a1c32', // Color primario gobierno
        margin: [0, 0, 0, 0]
      },
      headerDate: {
        fontSize: 9,
        color: '#6a1c32', // Color primario gobierno
        margin: [0, 0, 0, 0]
      },
      sectionTitle: {
        fontSize: 14,
        bold: true,
        color: '#6a1c32', // Color primario gobierno
        margin: [0, 15, 0, 10]
      },
      tableHeader: {
        bold: true,
        fontSize: 11,
        color: '#ffffff', // Texto blanco
        fillColor: '#6a1c32', // Fondo con color primario gobierno
        margin: [2, 2, 2, 2] // Padding equivalente a 1px CSS
      },
      tableCell: {
        fontSize: 10,
        margin: [2, 2, 2, 2] // Padding equivalente a 1px CSS
      },
      noData: {
        fontSize: 11,
        color: '#6a1c32', // Color primario gobierno
        fontStyle: 'italic'
      },
      footer: {
        fontSize: 9,
        color: '#6a1c32' // Color primario gobierno
      }
    };
  }

  /**
   * Obtiene el logo BC en formato base64
   */
  private async getLogoBase64(): Promise<string> {
    // Si ya está en caché, retornarlo
    if (logoCache) {
      return logoCache;
    }

    try {
      const response = await this.http.get('assets/BClogo.png', { responseType: 'blob' }).toPromise();
      if (response) {
        logoCache = await this.blobToBase64(response);
        return logoCache;
      }
      return '';
    } catch (error) {
      console.warn('No se pudo cargar el logo BC:', error);
      return '';
    }
  }

  /**
   * Convierte un Blob a base64
   */
  private blobToBase64(blob: Blob): Promise<string> {
    return new Promise((resolve, reject) => {
      const reader = new FileReader();
      reader.onloadend = () => {
        if (typeof reader.result === 'string') {
          // Extraer solo la parte base64 (sin el data:image/png;base64,)
          const base64Data = reader.result.split(',')[1] || reader.result;
          resolve(base64Data);
        } else {
          reject(new Error('Failed to convert blob to base64'));
        }
      };
      reader.onerror = reject;
      reader.readAsDataURL(blob);
    });
  }
}