import { Component, OnInit, inject } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { BaseChartDirective } from 'ng2-charts';
import { ChartData, ChartOptions, Chart, registerables } from 'chart.js';
import { ReportesUtilsService,
         ReportePorFolio,
         ReportePorEstatus,
         AvanceGeneral,
         FiltrosReporte,
         ReportePorDireccion } from '../../services/reportes-utils.service';
import { Pdf } from '../../services/pdf';

@Component({
  selector: 'app-reportes',
  imports: [CommonModule, FormsModule, BaseChartDirective],
  templateUrl: './reportes.html',
  styleUrl: './reportes.css'
})
export class Reportes implements OnInit {

  // Datos de reportes
  reportesPorFolio: ReportePorFolio[] = [];
  reportesPorEstatus: ReportePorEstatus[] = [];
  reportesPorDireccion: ReportePorDireccion[] = [];
  avanceGeneral: AvanceGeneral = {
    totalPropuestas: 0,
    porcentajeAvance: 0,
    propuestasATiempo: 0,
    propuestasRetrasadas: 0
  };

  // Filtros
  filtros: FiltrosReporte = {};

  // Opciones de fechas para filtros
  fechaInicio = '';
  fechaFin = '';

  // Configuración de gráficos
  graficoBarrasOptions: ChartOptions<'bar'> = {
    responsive: true,
    plugins: {
      legend: {
        position: 'top',
      },
      title: {
        display: true,
        text: 'Reportes por Folio'
      }
    }
  };

  graficoCircularOptions: ChartOptions<'doughnut'> = {
    responsive: true,
    plugins: {
      legend: {
        position: 'top',
      },
      title: {
        display: true,
        text: 'Distribución por Estatus'
      }
    }
  };

  graficoProgresoOptions: ChartOptions<'bar'> = {
    responsive: true,
    plugins: {
      legend: {
        position: 'top',
      },
      title: {
        display: true,
        text: 'Avance General del PMR'
      }
    },
    scales: {
      y: {
        beginAtZero: true,
        max: 100
      }
    }
  };

  private reportesService = inject(ReportesUtilsService);
  private pdfService = inject(Pdf);

  constructor() {
    // Registrar todos los componentes de Chart.js
    Chart.register(...registerables);
  }

  ngOnInit(): void {
    this.cargarReportes();
  }

  async cargarReportes(): Promise<void> {
    try {
      this.aplicarFiltros();
    } catch (error) {
      console.error('Error al cargar reportes:', error);
    }
  }

  async aplicarFiltros(): Promise<void> {
    // Preparar filtros
    const filtros: FiltrosReporte = {};

    if (this.fechaInicio) {
      filtros.fechaInicio = new Date(this.fechaInicio);
    }

    if (this.fechaFin) {
      filtros.fechaFin = new Date(this.fechaFin);
    }

    // Cargar todos los reportes con los filtros aplicados
    const [
      datosPorFolio,
      datosPorEstatus,
      datosPorDireccion,
      datosAvanceGeneral
    ] = await Promise.all([
      this.reportesService.getReportesPorFolio(filtros),
      this.reportesService.getReportesPorEstatus(filtros),
      this.reportesService.getReportesPorDireccion(filtros),
      this.reportesService.getAvanceGeneral(filtros)
    ]);

    this.reportesPorFolio = datosPorFolio;
    this.reportesPorEstatus = datosPorEstatus;
    this.reportesPorDireccion = datosPorDireccion;
    this.avanceGeneral = datosAvanceGeneral;
  }

  limpiarFiltros(): void {
    this.fechaInicio = '';
    this.fechaFin = '';
    this.filtros = {};
    this.cargarReportes();
  }

  // Getters para datos de gráficos
  get graficoBarrasData(): ChartData<'bar'> {
    return {
      labels: this.reportesPorFolio.map(r => r.folio),
      datasets: [{
        label: '% Completado',
        data: this.reportesPorFolio.map(r => r.porcentajeCompletado),
        backgroundColor: 'rgba(54, 162, 235, 0.6)',
        borderColor: 'rgba(54, 162, 235, 1)',
        borderWidth: 1
      }]
    };
  }

  get graficoCircularData(): ChartData<'doughnut'> {
    return {
      labels: this.reportesPorEstatus.map(r => r.estatus),
      datasets: [{
        data: this.reportesPorEstatus.map(r => r.total),
        backgroundColor: this.reportesPorEstatus.map(r => r.color),
        borderWidth: 1
      }]
    };
  }

  get graficoProgresoData(): ChartData<'bar'> {
    return {
      labels: ['Avance General'],
      datasets: [{
        label: '% Avance',
        data: [this.avanceGeneral.porcentajeAvance],
        backgroundColor: 'rgba(75, 192, 192, 0.6)',
        borderColor: 'rgba(75, 192, 192, 1)',
        borderWidth: 1
      }]
    };
  }

  // Método para exportar a PDF
  async exportarPDF(): Promise<void> {
    try {
      await this.pdfService.reporteGeneralPMR(
        this.avanceGeneral,
        this.reportesPorFolio,
        this.reportesPorEstatus,
        {
          includeTimestamp: true,
          includePageNumbers: true,
          title: 'Reporte General del Programa de Mejora Regulatoria'
        }
      );
    } catch (error) {
      console.error('Error al exportar a PDF:', error);
      alert('Ocurrió un error al generar el PDF. Por favor, inténtelo de nuevo.');
    }
  }
}
