import { Injectable } from '@angular/core';

@Injectable({
  providedIn: 'root'
})
export class FechaService {
  private readonly ZONA_HORARIA_DEFAULT = 'America/Tijuana';

  /**
   * Formatea una fecha del servidor usando la zona horaria de America/Tijuana
   * para asegurar consistencia en toda la aplicación
   */
  formatearFechaLocal(fecha: Date | string): string {
    if (!fecha) return '';

    let date: Date;

    // Si es string, crear objeto Date interpretando como America/Tijuana
    if (typeof fecha === 'string') {
      // Convertir YYYY-MM-DD HH:mm:ss a formato ISO para manejo correcto
      if (fecha.includes(' ')) {
        const [fechaPart, horaPart] = fecha.split(' ');
        const [anio, mes, dia] = fechaPart.split('-');
        const [hora, minutos, segundos] = horaPart.split(':');

        // Crear fecha usando constructor local (usa zona horaria del navegador)
        // Interpretamos que la fecha del servidor ya está en America/Tijuana
        date = new Date(
          parseInt(anio),
          parseInt(mes) - 1, // Meses en JS son 0-11
          parseInt(dia),
          parseInt(hora || '0'),
          parseInt(minutos || '0'),
          parseInt(segundos || '0')
        );
      } else {
        // Solo fecha sin hora
        const [anio, mes, dia] = fecha.split('-');
        date = new Date(
          parseInt(anio),
          parseInt(mes) - 1,
          parseInt(dia)
        );
      }
    } else {
      date = fecha;
    }

    // Formatear usando locale es-MX pero especificando America/Tijuana
    return date.toLocaleDateString('es-MX', {
      timeZone: this.ZONA_HORARIA_DEFAULT,
      day: '2-digit',
      month: '2-digit',
      year: 'numeric'
    });
  }

  /**
   * Obtiene la zona horaria configurada
   */
  getZonaHoraria(): string {
    return this.ZONA_HORARIA_DEFAULT;
  }

  /**
   * Convierte una fecha del filtro al formato esperado por el backend
   * Para la fecha inicial, usa 00:00:00
   * Para la fecha final, usa 23:59:59 para incluir todo el día
   */
  convertirFechaParaBackend(fecha: string, esFinal = false): string {
    if (!fecha) return '';

    // La fecha viene en formato YYYY-MM-DD del input date
    const [anio, mes, dia] = fecha.split('-');

    if (esFinal) {
      // Para fecha final, usar 23:59:59 para incluir todo el día
      return `${anio}-${mes}-${dia} 23:59:59`;
    } else {
      // Para fecha inicial, usar 00:00:00
      return `${anio}-${mes}-${dia} 00:00:00`;
    }
  }
}