import {CommonModule} from '@angular/common';
import {Component, inject, OnInit} from '@angular/core';
import {RouterLink} from '@angular/router';
import {FormBuilder, FormGroup, ReactiveFormsModule, Validators} from '@angular/forms';
import {PropuestasModel} from '../../../models/propuestas.model';
import {PropuestasService} from '../../../controllers/propuestas.service';
import {FechaService} from '../../../services/fecha.service';

@Component({
  selector: 'app-propuestas-registradas',
  imports: [CommonModule, RouterLink, ReactiveFormsModule],
  templateUrl: './propuestas-registradas.html',
  styleUrl: './propuestas-registradas.css'
})
export class PropuestasRegistradas implements OnInit {
  propuestas: PropuestasModel[] = [];
  isLoading = true;
  filtroForm!: FormGroup;
  fechasInvalidas = false;

  private fb = inject(FormBuilder);
  private propuestasService = inject(PropuestasService);
  private fechaService = inject(FechaService);

  async ngOnInit(): Promise<void> {
    this.inicializarFormulario();
    await this.cargarPropuestas();
    this.isLoading = false;
  }

  async cargarPropuestas(): Promise<void> {
    try {
      const response = await this.propuestasService.all({
        relations: ['user', 'tiempoActualUnidad', 'tiempoEsperadoUnidad', 'documentos']
      });
      this.propuestas = response || [];
    } catch (error) {
      console.error('Error al cargar las propuestas:', error);
      this.propuestas = [];
    }
  }

  async cargarPropuestasConFiltros(): Promise<void> {
    try {
      this.isLoading = true;
      const fechaInicial = this.filtroForm.get('fechaInicial')?.value;
      const fechaFinal = this.filtroForm.get('fechaFinal')?.value;
      const tipoFiltro = this.filtroForm.get('tipoFiltro')?.value;

      const conditionals: {key: string, operator: string, value: string}[] = [];

      if (fechaInicial && fechaFinal) {
        // Convertir las fechas al formato esperado por el backend
        const fechaInicialBackend = this.fechaService.convertirFechaParaBackend(fechaInicial, false);
        const fechaFinalBackend = this.fechaService.convertirFechaParaBackend(fechaFinal, true);

        conditionals.push(
          { key: tipoFiltro, operator: '>=', value: fechaInicialBackend },
          { key: tipoFiltro, operator: '<=', value: fechaFinalBackend }
        );
      }

      const response = await this.propuestasService.all({
        conditionals,
        relations: ['user', 'tiempoActualUnidad', 'tiempoEsperadoUnidad', 'documentos'],
        loader: true,
      });

      this.propuestas = response || [];
    } catch (error) {
      console.error('Error al cargar las propuestas con filtros:', error);
      this.propuestas = [];
    } finally {
      this.isLoading = false;
    }
  }

  inicializarFormulario(): void {
    this.filtroForm = this.fb.group({
      fechaInicial: ['', Validators.required],
      fechaFinal: ['', Validators.required],
      tipoFiltro: ['fecha_cumplimiento', Validators.required]
    });

    // Escuchar cambios en las fechas para validar
    this.filtroForm.get('fechaInicial')?.valueChanges.subscribe(() => {
      this.validarFechas();
    });

    this.filtroForm.get('fechaFinal')?.valueChanges.subscribe(() => {
      this.validarFechas();
    });
  }

  validarFechas(): void {
    const fechaInicial = this.filtroForm.get('fechaInicial')?.value;
    const fechaFinal = this.filtroForm.get('fechaFinal')?.value;

    this.fechasInvalidas = false;

    if (fechaInicial && fechaFinal) {
      this.fechasInvalidas = new Date(fechaFinal) < new Date(fechaInicial);
    }
  }

  async aplicarFiltro(): Promise<void> {
    if (this.filtroForm.invalid || this.fechasInvalidas) {
      return;
    }

    await this.cargarPropuestasConFiltros();
  }

  async limpiarFiltros(): Promise<void> {
    this.filtroForm.reset({
      fechaInicial: '',
      fechaFinal: '',
      tipoFiltro: 'fecha_cumplimiento'
    });
    this.fechasInvalidas = false;

    this.isLoading = true;
    await this.cargarPropuestas();
    this.isLoading = false;
  }

  get hayFiltrosActivos(): boolean {
    return !!(this.filtroForm.get('fechaInicial')?.value && this.filtroForm.get('fechaFinal')?.value);
  }

  getTipoFiltroDescripcion(): string {
    const tipo = this.filtroForm.get('tipoFiltro')?.value;
    return tipo === 'fecha_cumplimiento' ? 'fecha de cumplimiento' : 'fecha de creación';
  }

  getRowButtons() {
    return [
      { key: 'view', text: 'Ver Detalle' }
    ];
  }

  formatearFecha(fecha: Date | string): string {
    return this.fechaService.formatearFechaLocal(fecha);
  }

  getPropuestasByTipo(tipo: 'Tramite' | 'Servicio'): PropuestasModel[] {
    return this.propuestas.filter(propuesta => propuesta.tipo === tipo);
  }

  getUniqueUsers(): number {
    const uniqueUsers = new Set(this.propuestas.map(propuesta => propuesta.user_id));
    return uniqueUsers.size;
  }

  getFechaClass(fecha: Date | string): string {
    const fechaLimite = new Date(fecha);
    const hoy = new Date();
    const diasRestantes = Math.ceil((fechaLimite.getTime() - hoy.getTime()) / (1000 * 60 * 60 * 24));

    if (diasRestantes < 0) {
      return 'text-danger';
    } else if (diasRestantes <= 7) {
      return 'text-warning';
    } else {
      return 'text-success';
    }
  }

  getDiasRestantes(fecha: Date | string): string {
    const fechaLimite = new Date(fecha);
    const hoy = new Date();
    const diasRestantes = Math.ceil((fechaLimite.getTime() - hoy.getTime()) / (1000 * 60 * 60 * 24));

    if (diasRestantes < 0) {
      return `Vencida hace ${Math.abs(diasRestantes)} días`;
    } else if (diasRestantes === 0) {
      return 'Vence hoy';
    } else if (diasRestantes === 1) {
      return 'Mañana';
    } else if (diasRestantes <= 7) {
      return `${diasRestantes} días restantes`;
    } else {
      return `${diasRestantes} días`;
    }
  }
}
