import { Component, Input, AfterViewChecked, ViewChild, ElementRef, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { DatePipe } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { PropuestaFeedbackService } from '../../../../controllers/propuesta-feedback.service';
import { PropuestaFeedbackModel } from '../../../../models/propuesta-feedback.model';
import { Usuario } from '../../../../models/usuario';
import { UtilsService } from '../../../../services/utils.service';
import { LocalStorageService } from '../../../../services/localStorage/local-storage.service';

@Component({
  selector: 'app-feedback-interno',
  imports: [
    CommonModule,
    FormsModule
  ],
  templateUrl: './feedback-interno.html',
  styleUrl: './feedback-interno.css'
})
export class FeedbackInterno implements AfterViewChecked, OnInit {
  @Input() propuestaId: number | null = null;
  @ViewChild('chatContainer') chatContainer!: ElementRef;

  private feedbackService = inject(PropuestaFeedbackService);
  private utilsService = inject(UtilsService);
  private storage = inject(LocalStorageService);

  comentarios: PropuestaFeedbackModel[] = [];
  nuevoComentario = '';
  isLoading = false;
  error: string | null = null;

  // Usuario logeado obtenido del sistema de autenticación
  get currentUser(): Usuario | null {
    const userData = this.storage.getUser();
    return userData?.user || null;
  }

  private shouldScroll = false;

  async ngOnInit(): Promise<void> {
    await this.cargarFeedback();
  }

  async cargarFeedback(): Promise<void> {
    if (this.propuestaId) {
      try {
        const response = await this.feedbackService.get({
          conditionals: [{ key: 'propuesta_id', operator: '=', value: this.propuestaId }],
          relations: ['user']
        });

        if (response.status && response.data) {
          this.comentarios = response.data;
          this.shouldScroll = true;
        }
      } catch (error) {
        console.error('Error al cargar feedback:', error);
        this.error = 'Error al cargar los comentarios';
      }
    }
  }

  async agregarComentario(): Promise<void> {
    if (this.nuevoComentario.trim() && this.propuestaId && this.currentUser) {
      const nuevoFeedback: Partial<PropuestaFeedbackModel> = {
        propuesta_id: this.propuestaId,
        texto: this.nuevoComentario,
        fecha: this.utilsService.toMySQLDateTime(new Date())!,
        user_id: this.currentUser.id,
        es_propietario: false // Usuarios internos no son propietarios por defecto
      };

      try {
        const response = await this.feedbackService.new(nuevoFeedback);
        if (response) {
          // Recargar comentarios para obtener datos actualizados
          await this.cargarFeedback();
          this.nuevoComentario = '';
          this.shouldScroll = true;
        }
      } catch (error) {
        console.error('Error al agregar comentario:', error);
        this.error = 'Error al agregar comentario';
      }
    }
  }

  // Manejo de teclado para enviar mensaje con Enter
  async onKeyPress(event: KeyboardEvent): Promise<void> {
    if (event.key === 'Enter' && !event.shiftKey) {
      event.preventDefault();
      await this.agregarComentario();
    }
  }

  // Auto-scroll al último mensaje
  ngAfterViewChecked(): void {
    if (this.shouldScroll && this.chatContainer) {
      try {
        this.chatContainer.nativeElement.scrollTop = this.chatContainer.nativeElement.scrollHeight;
      } catch (err) {
        console.error('Error al hacer scroll:', err);
      }
      this.shouldScroll = false;
    }
  }

  // Verificar si hay usuario autenticado
  isAuthenticated(): boolean {
    return this.currentUser !== null;
  }

  // Verificar si el usuario está escribiendo (para futura implementación)
  isTyping(): boolean {
    return this.nuevoComentario.trim().length > 0;
  }

  // Métodos de utilidad para el template
  formatearFecha(fecha: string | Date | null | undefined): string {
    if (!fecha) return 'N/A';
    const datePipe = new DatePipe('en-US');
    return datePipe.transform(fecha, 'dd/MM/yyyy HH:mm') || 'N/A';
  }

  formatearFechaRelativa(fecha: string | Date | null | undefined): string {
    if (!fecha) return 'N/A';

    const fechaComentario = new Date(fecha);
    const ahora = new Date();
    const diferencia = ahora.getTime() - fechaComentario.getTime();
    const minutos = Math.floor(diferencia / (1000 * 60));
    const horas = Math.floor(minutos / 60);
    const dias = Math.floor(horas / 24);

    if (minutos < 1) return 'Ahora';
    if (minutos < 60) return `Hace ${minutos} min`;
    if (horas < 24) return `Hace ${horas} h`;
    if (dias < 7) return `Hace ${dias} días`;

    return this.formatearFecha(fecha);
  }

  esComentarioPropio(comentario: PropuestaFeedbackModel): boolean {
    return comentario.user_id === this.currentUser?.id;
  }

  getRolBadgeClass(esPropietario: boolean | undefined): string {
    if (esPropietario) return 'badge-propietario';
    return 'badge-interno';
  }

  getRolBadgeText(esPropietario: boolean | undefined, esPropio: boolean): string {
    if (esPropietario) return 'Propietario';
    if (esPropio) return 'Tú';
    return 'Interno';
  }

  getMensajeClass(esPropio: boolean): string {
    if (esPropio) return 'mensaje-propio';
    return 'mensaje-otro';
  }
}
