import { Component, Input, Output, EventEmitter, inject } from '@angular/core';
import { CommonModule, DatePipe } from '@angular/common';
import { PropuestaEvidenciaModel } from '../../../../models/propuesta-evidencia.model';

@Component({
  selector: 'app-evidencias-component',
  imports: [CommonModule],
  templateUrl: './evidencias-component.html',
  styleUrl: './evidencias-component.css'
})
export class EvidenciasComponent {
  @Input() evidencias: PropuestaEvidenciaModel[] = [];
  @Input() isLoading = false;
  @Output() descargarEvidencia = new EventEmitter<number>();

  private datePipe = inject(DatePipe);

  /**
   * Formatear fecha para mostrar
   */
  formatearFecha(fecha: string | Date | null | undefined): string {
    if (!fecha) return 'N/A';
    return this.datePipe.transform(fecha, 'dd/MM/yyyy') || 'N/A';
  }

  /**
   * Manejar descarga de evidencia
   */
  onDescargarEvidencia(evidenciaId: number): void {
    this.descargarEvidencia.emit(evidenciaId);
  }

  /**
   * Formatear tamaño de archivo para mostrar
   */
  formatFileSize(bytes: number): string {
    if (bytes === 0) return '0 Bytes';
    const k = 1024;
    const sizes = ['Bytes', 'KB', 'MB', 'GB'];
    const i = Math.floor(Math.log(bytes) / Math.log(k));
    return parseFloat((bytes / Math.pow(k, i)).toFixed(2)) + ' ' + sizes[i];
  }
}
